from datetime import date, timedelta

def add_business_days(start, n):
    d = date.fromisoformat(start)
    added = 0
    while added < n:
        d += timedelta(days=1)
        if d.weekday() < 5:
            added += 1
    return d.isoformat()

def brace_expand(s):
    parts = []
    i = 0
    while i < len(s):
        if s[i] == '{':
            j = s.index('}', i)
            opts = s[i+1:j].split(',')
            if len(opts) == 1:
                parts.append(['{' + opts[0] + '}'])
            else:
                parts.append(opts)
            i = j + 1
        else:
            j = i
            while j < len(s) and s[j] != '{':
                j += 1
            parts.append([s[i:j]])
            i = j
    out = ['']
    for opts in parts:
        out = [p + o for p in out for o in opts]
    return out

def sudoku_valid(board):
    def ok(cells):
        d = [c for c in cells if c != '.']
        return len(d) == len(set(d))
    for i in range(9):
        if not ok(board[i]):
            return False
        if not ok(board[r][i] for r in range(9)):
            return False
        br, bc = 3 * (i // 3), 3 * (i % 3)
        if not ok(board[r][c] for r in range(br, br+3) for c in range(bc, bc+3)):
            return False
    return True

def words_to_number(text):
    units = {'zero':0,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,
             'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12,
             'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,
             'seventeen':17,'eighteen':18,'nineteen':19}
    tens = {'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,
            'seventy':70,'eighty':80,'ninety':90}
    total, current = 0, 0
    for w in text.replace('-', ' ').split():
        if w in units:
            current += units[w]
        elif w in tens:
            current += tens[w]
        elif w == 'hundred':
            current *= 100
        elif w == 'thousand':
            total += current * 1000
            current = 0
        else:
            raise ValueError('unknown word: ' + w)
    return total + current

def parse_md_table(text):
    lines = [l for l in text.strip().splitlines() if l.strip()]
    def cells(line):
        line = line.strip()
        if line.startswith('|'):
            line = line[1:]
        if line.endswith('|'):
            line = line[:-1]
        return [c.strip() for c in line.split('|')]
    header = cells(lines[0])
    rows = []
    for line in lines[2:]:
        vals = cells(line)
        rows.append(dict(zip(header, vals)))
    return rows
